#include <iostream>
#include <string>
#include <vector>
#include <queue>
#include <climits>
#include <algorithm>
using namespace std;

int N;
vector<string> gridA, gridB;
vector<vector<int>> shortest_paths;

struct FlowEdge {
    int u, v;
    int capacity, cost;
    FlowEdge(int from, int to, int cap, int c) : u(from), v(to), capacity(cap), cost(c) {}
};

struct MinCostFlow {
    int n;
    vector<int> dist, prev_flow, prev_edge;
    vector<FlowEdge> edges;
    int max_flow, min_cost;

    void setup(int size) {
        n = size;
        dist.assign(n, INT_MAX);
        prev_flow.assign(n, 0);
        prev_edge.assign(n, -1);
    }

    void link(int from, int to, int cap, int cost) {
        edges.emplace_back(from, to, cap, cost);
        edges.emplace_back(to, from, 0, -cost);
    }

    void spfa(int src, int dst) {
        setup(n);
        prev_flow[src] = INT_MAX;
        dist[src] = 0;
        queue<int> q;
        q.push(src);
        vector<bool> in_queue(n, false);
        in_queue[src] = true;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            in_queue[u] = false;
            for (size_t i = 0; i < edges.size(); ++i) {
                auto& e = edges[i];
                if (e.capacity > 0 && dist[e.v] > dist[e.u] + e.cost) {
                    dist[e.v] = dist[e.u] + e.cost;
                    prev_flow[e.v] = min(prev_flow[e.u], e.capacity);
                    prev_edge[e.v] = i;
                    if (!in_queue[e.v]) {
                        q.push(e.v);
                        in_queue[e.v] = true;
                    }
                }
            }
        }
    }

    void solve(int src, int dst) {
        if (src == dst) {
            max_flow = INT_MAX;
            min_cost = 0;
            return;
        }
        max_flow = 0;
        min_cost = 0;
        while (true) {
            spfa(src, dst);
            if (prev_flow[dst] == 0) break;
            for (int cur = dst; cur != src; cur = edges[prev_edge[cur]].u) {
                int rev = prev_edge[cur] ^ 1;
                edges[prev_edge[cur]].capacity -= prev_flow[dst];
                edges[rev].capacity += prev_flow[dst];
                min_cost += edges[prev_edge[cur]].cost * prev_flow[dst];
            }
            max_flow += prev_flow[dst];
        }
    }
};

#define IN_NODE(x) (2 * (x))
#define OUT_NODE(x) (2 * (x) + 1)

MinCostFlow mcf;
const int INF = 1000000000;
int dirX[4] = {-1, 0, 1, 0};
int dirY[4] = {0, 1, 0, -1};

void bfs_search(int sx, int sy, vector<vector<int>>& dist) {
    dist.assign(N, vector<int>(N, -1));
    dist[sx][sy] = 0;
    queue<int> q;
    q.push(sx * N + sy);
    while (!q.empty()) {
        int cur = q.front(); q.pop();
        int x = cur / N, y = cur % N;
        for (int i = 0; i < 4; ++i) {
            int nx = x + dirX[i], ny = y + dirY[i];
            if (nx < 0 || nx >= N || ny < 0 || ny >= N || dist[nx][ny] != -1 || gridA[nx][ny] == 'Y') continue;
            if (isdigit(gridB[nx][ny]) && gridB[nx][ny] != '0' && (dist[x][y] + 1 <= shortest_paths[nx][ny] || shortest_paths[nx][ny] == -1)) {
                dist[nx][ny] = dist[x][y] + 1;
                if (dist[nx][ny] != shortest_paths[nx][ny]) q.push(nx * N + ny);
            } else if (shortest_paths[nx][ny] == -1 || shortest_paths[nx][ny] > dist[x][y] + 1) {
                dist[nx][ny] = dist[x][y] + 1;
                q.push(nx * N + ny);
            }
        }
    }
}

void build_distance_tables(vector<string>& m, vector<vector<vector<int>>>& all_dists) {
    all_dists.resize(N * N);
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            if (isdigit(m[i][j]) && m[i][j] != '0')
                bfs_search(i, j, all_dists[i * N + j]);
}

void connect_nodes(int i1, int j1, int i2, int j2) {
    int u = i1 * N + j1;
    int v = i2 * N + j2 + N * N;
    mcf.link(OUT_NODE(u), IN_NODE(v), 1000000, 0);
}

int main() {
#ifndef ONLINE_JUDGE
    freopen("in.txt", "rt", stdin);
#endif
    int n, t;
    cin >> n >> t;
    N = n;
    vector<string> A(n), B(n);
    int start_x = -1, start_y = -1;
    for (int i = 0; i < n; ++i) {
        cin >> A[i];
        for (int j = 0; j < n; ++j)
            if (A[i][j] == 'Z') {
                start_x = i;
                start_y = j;
            }
    }
    gridA = A;
    for (int i = 0; i < n; ++i) cin >> B[i];
    gridB = B;
    vector<vector<int>> temp_dist;
    vector<vector<vector<int>>> all_dists;
    shortest_paths.assign(N, vector<int>(N, INF));
    bfs_search(start_x, start_y, temp_dist);
    shortest_paths = temp_dist;
    build_distance_tables(A, all_dists);
    mcf.setup(4 * N * N + 2);
    int source = 4 * N * N, sink = source + 1;
    for (int i = 0; i < N * N; ++i) {
        mcf.link(source, IN_NODE(i), 1000000, 0);
        mcf.link(OUT_NODE(N * N + i), sink, 1000000, 0);
    }
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j) {
            if (isdigit(A[i][j])) {
                int idx = i * N + j;
                mcf.link(IN_NODE(idx), OUT_NODE(idx), 0, A[i][j] - '0');
            }
            if (isdigit(B[i][j])) {
                int idx = i * N + j + N * N;
                mcf.link(IN_NODE(idx), OUT_NODE(idx), 0, B[i][j] - '0');
            }
        }
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            if (isdigit(B[i][j]) && B[i][j] != '0')
                for (int k = 0; k < (int)all_dists.size(); ++k)
                    if (!all_dists[k].empty()) {
                        int x = k / N, y = k % N;
                        if (all_dists[k][i][j] == -1 || all_dists[k][i][j] > t) continue;
                        connect_nodes(x, y, i, j);
                    }
    mcf.solve(source, sink);
    cout << mcf.max_flow << endl;
    return 0;
}
